SELECT year, AVG(weight) AS average_weight
FROM cars_data
GROUP BY year;

SELECT AVG(Weight) AS average_weight, Year
FROM cars_data
GROUP BY Year;

SELECT other_student_details, first_name, last_name 
FROM Students 
ORDER BY last_name DESC, first_name DESC;

SELECT student_id, COUNT(friend_id) AS number_of_friends
FROM Friend
GROUP BY student_id;
